               <div className="px-2 py-0.5 bg-blue-500/10 text-blue-400 text-[10px] font-bold rounded">{upcomingSessions.length}</div>
            </div>
            <div className="space-y-4">
               {upcomingSessions.map(s => (
                 <div key={s.id} className="modern-card p-6 hover:border-blue-500/30 transition-all cursor-pointer" onClick={() => onSessionClick(s.id)}>
                    <div className="flex justify-between items-center mb-6">
                       <span className="bg-blue-500/10 text-blue-400 text-[10px] font-bold px-3 py-1 rounded-full border border-blue-500/20">{s.category}</span>
                       <ActivityCountdown date={s.date} time={s.time} />
                    </div>
                    <h3 className="text-lg font-bold text-white mb-2">{s.objective}</h3>
                    <div className="flex gap-4 text-[10px] font-bold text-slate-400 uppercase">
                       <span className="flex items-center gap-2"><Calendar size={14} className="text-slate-600"/> {s.date}</span>
                       <span className="flex items-center gap-2"><Clock size={14} className="text-slate-600"/> {s.time}</span>
                    </div>
                 </div>
               ))}
            </div>
         </div>
      </div>
    </div>
  );
};

export default Dashboard;

