const ActivityCountdown: React.FC<{ date: string; time: string }> = ({ date, time }) => {
  const [timeLeft, setTimeLeft] = useState<{ d: number; h: number; m: number; s: number } | null>(null);

  useEffect(() => {
    const calculateTime = () => {
      const target = new Date(`${date}T${time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();
      if (diff <= 0) { setTimeLeft(null); return; }
      setTimeLeft({
        d: Math.floor(diff / (1000 * 60 * 60 * 24)),
        h: Math.floor((diff / (1000 * 60 * 60)) % 24),
        m: Math.floor((diff / (1000 * 60)) % 60),
        s: Math.floor((diff / 1000) % 60)
      });
    };
    calculateTime();
    const timer = setInterval(calculateTime, 1000);
    return () => clearInterval(timer);
  }, [date, time]);

  if (!timeLeft) return (
    <div className="flex items-center gap-2 px-3 py-1 bg-emerald-500/10 text-emerald-400 rounded-lg text-[10px] font-bold uppercase tracking-widest border border-emerald-500/20">
      <Zap size={12} /> النشاط جارٍ
    </div>
  );

  return (
    <div className="flex gap-2 items-center text-slate-400 bg-slate-900/50 px-4 py-2 rounded-xl border border-white/5">
      <div className="flex flex-col items-center"><span className="text-lg font-bold text-white tabular-nums leading-none">{timeLeft.d}</span><span className="text-[8px] uppercase tracking-tighter opacity-50 mt-1">يوم</span></div>
      <span className="opacity-20">:</span>
      <div className="flex flex-col items-center"><span className="text-lg font-bold text-white tabular-nums leading-none">{String(timeLeft.h).padStart(2, '0')}</span><span className="text-[8px] uppercase tracking-tighter opacity-50 mt-1">سا</span></div>
      <span className="opacity-20">:</span>
      <div className="flex flex-col items-center"><span className="text-lg font-bold text-white tabular-nums leading-none">{String(timeLeft.m).padStart(2, '0')}</span><span className="text-[8px] uppercase tracking-tighter opacity-50 mt-1">د</span></div>
      <span className="opacity-20">:</span>
      <div className="flex flex-col items-center"><span className="text-lg font-bold text-orange-500 tabular-nums leading-none">{String(timeLeft.s).padStart(2, '0')}</span><span className="text-[8px] uppercase tracking-tighter opacity-50 mt-1">ث</span></div>
    </div>
  );
};

