import React, { useState } from 'react';
import { ShieldCheck, UserPlus, X, Edit2, Trash2, Key, ShieldAlert, Eye, EyeOff, Loader2, Save } from 'lucide-react';
import { AppState, AppUser, UserRole } from '../types';
import { generateUUID, supabase } from '../App';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');
  const [showPassInForm, setShowPassInForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const currentUser = state.currentUser;
  const isGlobalManager = currentUser?.role === 'مدير';

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة',
    password: '',
    restrictedCategory: ''
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد', 'أمين مستودع'];

  const handleSaveUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username || !userFormData.password || isSaving) return;

    setIsSaving(true);
    const userId = editingUserId || generateUUID();
    const newUser: AppUser = {
      id: userId,
      username: userFormData.username!.trim(),
      role: userFormData.role as UserRole,
      password: userFormData.password!,
      restrictedCategory: (userFormData.role === 'إداري فئة' || userFormData.role === 'مشاهد') ? userFormData.restrictedCategory : undefined
    };

    try {
      // رفع البيانات للسحابة (الخطوة التي كانت ناقصة)
      const { error } = await supabase.from('app_users').upsert(newUser);
      if (error) throw error;

      setState(prev => ({
        ...prev,
        users: editingUserId 
          ? prev.users.map(u => u.id === editingUserId ? newUser : u)
          : [...prev.users, newUser]
      }));

      addLog?.(editingUserId ? 'تم تحديث الصلاحيات' : 'تم تفعيل حساب جديد', `المستخدم: ${newUser.username}`, 'success');
      setIsUserModalOpen(false);
      setEditingUserId(null);
      setUserFormData({ username: '', role: 'إداري فئة', password: '', restrictedCategory: '' });
    } catch (err: any) {
      alert("خطأ في حفظ الحساب سحابياً: " + err.message);
    } finally {
      setIsSaving(false);
    }
  };

  const deleteUser = async (id: string, name: string) => {
    if (id === 'root' || name.toUpperCase() === 'IZZAT') return alert('لا يمكن حذف حساب الطوارئ الجذري.');
    if (confirm(`هل أنت متأكد من حذف حساب ${name} نهائياً؟`)) {
      try {
        const { error } = await supabase.from('app_users').delete().eq('id', id);
        if (error) throw error;
        setState(p => ({ ...p, users: p.users.filter(u => u.id !== id) }));
        addLog?.('حذف مستخدم', `تم مسح حساب: ${name}`, 'error');
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      }
    }
  };

  const labelClass = "text-[11px] font-black text-slate-400 mr-2 uppercase block mb-1.5 tracking-widest";
  const fieldClass = "w-full bg-[#020617] border border-white/10 rounded-2xl py-4 px-6 font-bold text-white outline-none focus:border-orange-500 transition-all";

  return (
    <div className="space-y-12 pb-24 font-['IBM_Plex_Sans_Arabic'] text-right" dir="rtl">
      {isGlobalManager && (
        <div className="modern-card p-10 border-b-8 border-orange-500/20">
           <div className="flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
              <div>
                <h3 className="text-3xl font-black text-white flex items-center gap-4">
                  <ShieldCheck size={40} className="text-orange-500" /> إدارة النفاذ الرقمي (Eagle Access)
                </h3>
                <p className="text-[10px] font-black text-slate-500 mt-2 uppercase tracking-[0.3em]">Cloud-Based User Authentication Center</p>
              </div>
              <button onClick={() => { setEditingUserId(null); setUserFormData({username:'', role:'إداري فئة', password:'', restrictedCategory:''}); setIsUserModalOpen(true); }} 
                className="bg-orange-500 text-white px-8 py-4 rounded-2xl font-black text-sm flex items-center gap-3 shadow-lg shadow-orange-500/20 hover:bg-orange-600 transition-all">
                <UserPlus size={20}/> إضافة حساب سحابي
              </button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {state.users.map(user => (
                <div key={user.id} className="bg-white/5 border border-white/5 p-6 rounded-[2.5rem] group hover:border-orange-500/40 transition-all relative overflow-hidden">
                   <div className="flex justify-between items-start mb-6">
                      <div className="w-12 h-12 bg-slate-800 rounded-2xl flex items-center justify-center border border-white/10">
                         <Key size={20} className="text-orange-500"/>
                      </div>
                      <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase border shadow-sm ${user.role === 'مدير' ? 'bg-orange-500 text-white border-orange-400' : 'bg-blue-600 text-white border-blue-400'}`}>
                        {user.role}
                      </span>
                   </div>
                   <h4 className="font-black text-xl text-white">{user.username}</h4>
                   <p className="text-[10px] font-bold text-slate-500 mt-1 truncate">
                      {user.restrictedCategory ? `الوصول: ${user.restrictedCategory}` : 'صلاحيات إدارية كاملة'}
                   </p>
                   <div className="mt-6 pt-6 border-t border-white/5 flex justify-end gap-2">
                      <button onClick={() => { setEditingUserId(user.id); setUserFormData(user); setIsUserModalOpen(true); }} className="p-2.5 bg-white/5 text-blue-400 rounded-xl hover:bg-blue-500 hover:text-white transition-all"><Edit2 size={16}/></button>
                      <button onClick={() => deleteUser(user.id, user.username)} className="p-2.5 bg-white/5 text-red-400 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 size={16}/></button>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* مودال إنشاء المستخدم المحدث */}
      {isUserModalOpen && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-md flex items-center justify-center z-[1000] p-4">
          <div className="relative bg-[#0f172a] border-2 border-white/10 w-full max-w-xl rounded-[2.5rem] overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-white/5 flex justify-between items-center bg-white/5">
               <h3 className="text-xl font-black text-white uppercase">برمجة وصول مستخدم</h3>
               <button onClick={() => setIsUserModalOpen(false)} className="p-2 hover:bg-white/5 rounded-xl transition-all text-slate-400"><X/></button>
            </div>
            <form onSubmit={handleSaveUser} className="p-10 space-y-6">
              <div className="space-y-1">
                <label className={labelClass}>اسم المستخدم (Username)</label>
                <input required type="text" value={userFormData.username || ''} onChange={e => setUserFormData({ ...userFormData, username: e.target.value })}
                  className={fieldClass} placeholder="أدخل اسم فريد للدخول..." />
              </div>

              <div className="space-y-1">
                <label className={labelClass}>كلمة المرور السحابية</label>
                <div className="relative">
                   <input required type={showPassInForm ? "text" : "password"} value={userFormData.password || ''} onChange={e => setUserFormData({ ...userFormData, password: e.target.value })}
                    className={fieldClass} placeholder="••••••••" />
                   <button type="button" onClick={() => setShowPassInForm(!showPassInForm)} className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white">
                      {showPassInForm ? <EyeOff size={20}/> : <Eye size={20}/>}
                   </button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-1">
                    <label className={labelClass}>نوع الصلاحية</label>
                    <select className={fieldClass}
                      value={userFormData.role} onChange={e => setUserFormData({ ...userFormData, role: e.target.value as UserRole, restrictedCategory: '' })}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                 </div>
                 {(userFormData.role === 'إداري فئة' || userFormData.role === 'مشاهد') && (
                    <div className="space-y-1">
                      <label className={labelClass}>الفئة المحصورة</label>
                      <select className={fieldClass}
                        value={userFormData.restrictedCategory} onChange={e => setUserFormData({ ...userFormData, restrictedCategory: e.target.value })}>
                        <option value="">-- اختر الفئة --</option>
                        {state.categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                      </select>
                    </div>
                 )}
              </div>

